import { getTelemetryMode } from '../config/telemetryPolicy';
import { randomUUID } from 'crypto';
import log from 'loglevel';
import { PROXY_URL } from '../config/proxy';
import { RIVET_VERSION } from '../config/telemetry';
import { getConfigManager } from './ConfigManager';

type ForwardedLogEntry = {
  level: string;
  message: string;
  timestamp: number;
  metadata?: Record<string, unknown>;
};

const FLUSH_INTERVAL_MS = 5_000;
const MAX_BUFFER_ENTRIES = 1_000;
const CAPTURED_LEVELS = new Set(['info', 'warn', 'error']);
const LOG_SOURCE = 'cli-server';

const stringifyLogArg = (arg: unknown): string => {
  if (typeof arg === 'string') return arg;
  if (arg instanceof Error) return arg.stack || arg.message;
  try {
    return JSON.stringify(arg);
  } catch {
    return String(arg);
  }
};

export class CliLogForwarder {
  private buffer: ForwardedLogEntry[] = [];
  private droppedEntries = 0;
  private readonly sessionId = randomUUID();
  private flushTimer: NodeJS.Timeout | null = null;
  private isInitialized = false;
  private readonly isEnabled: boolean;

  constructor(options: { enabled?: boolean } = {}) {
    this.isEnabled = (options.enabled ?? true) && getTelemetryMode() === 'full';
  }

  init(): void {
    if (!this.isEnabled || this.isInitialized) {
      return;
    }
    this.isInitialized = true;

    const previousFactory = log.methodFactory;
    log.methodFactory = (methodName, logLevel, loggerName) => {
      const rawMethod = previousFactory(methodName, logLevel, loggerName);
      if (!CAPTURED_LEVELS.has(methodName)) {
        return rawMethod;
      }
      return (message: unknown, ...args: unknown[]) => {
        rawMethod(message, ...args);
        this.capture(methodName, [message, ...args]);
      };
    };
    log.setLevel(log.getLevel());

    this.flushTimer = setInterval(() => {
      void this.flush();
    }, FLUSH_INTERVAL_MS);
    this.flushTimer.unref();
  }

  private capture(level: string, args: unknown[]): void {
    if (this.buffer.length >= MAX_BUFFER_ENTRIES) {
      this.buffer.shift();
      this.droppedEntries++;
    }
    this.buffer.push({
      level,
      message: args.map(stringifyLogArg).join(' '),
      timestamp: Date.now(),
      metadata: { emit_event: false },
    });

    if (level === 'error') {
      void this.flush();
    }
  }

  private distinctId(): string {
    try {
      const cm = getConfigManager();
      return cm.getUserId() ?? cm.getEmail() ?? cm.getAnonymousId();
    } catch {
      return `anon-${this.sessionId}`;
    }
  }

  private async flush(): Promise<void> {
    if (this.buffer.length === 0) {
      return;
    }
    const logs = this.buffer;
    this.buffer = [];
    if (this.droppedEntries > 0) {
      logs.push({
        level: 'warn',
        message: `[CliLogForwarder] dropped ${this.droppedEntries} entries (buffer cap ${MAX_BUFFER_ENTRIES})`,
        timestamp: Date.now(),
        metadata: { emit_event: false },
      });
      this.droppedEntries = 0;
    }

    try {
      const response = await fetch(`${PROXY_URL}/api/logs`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          distinctId: this.distinctId(),
          sessionId: this.sessionId,
          rivet_version: RIVET_VERSION,
          source: LOG_SOURCE,
          logs,
        }),
      });
      if (!response.ok) {
        process.stderr.write(
          `[CliLogForwarder] proxy returned ${response.status}; ${logs.length} entries lost\n`,
        );
      }
    } catch (error) {
      process.stderr.write(`[CliLogForwarder] flush failed: ${error}\n`);
    }
  }

  async shutdown(): Promise<void> {
    if (this.flushTimer) {
      clearInterval(this.flushTimer);
      this.flushTimer = null;
    }
    await this.flush();
  }
}
